# Instead, let's check the sign of f at many points.

# For x in various intervals, compute L(x) and R(x) using logs to avoid overflow.

import math

def log_prod(x, factors):
    """Compute log|prod(x - k)| and sign separately."""
    log_abs = 0.0
    sign = 1
    for k in factors:
        diff = x - k
        if abs(diff) < 1e-15:
            return 0.0, 0  # exactly zero
        log_abs += math.log(abs(diff))
        if diff < 0:
            sign *= -1
    return log_abs, sign

def f_value(x, A, B):
    """Compute sign and log|f(x)| = L(x) - R(x)."""
    log_L, sign_L = log_prod(x, A)
    log_R, sign_R = log_prod(x, B)

    if sign_L == 0:
        # L(x) = 0, so f(x) = -R(x)
        return -sign_R, log_R
    if sign_R == 0:
        # R(x) = 0, so f(x) = L(x)
        return sign_L, log_L

    # f = sign_L * exp(log_L) - sign_R * exp(log_R)
    # If signs differ, f has the sign of the larger magnitude term
    if sign_L != sign_R:
        if log_L > log_R:
            return sign_L, log_L + math.log(1 - math.exp(log_R - log_L))
        else:
            return -sign_R, log_R + math.log(1 - math.exp(log_L - log_R))
    else:
        # Same sign, need to compare magnitudes
        if log_L > log_R:
            return sign_L, log_L + math.log(1 - math.exp(log_R - log_L))
        elif log_R > log_L:
            return -sign_R, log_R + math.log(math.exp(log_L - log_R) - 1) if sign_L > 0 else sign_R, log_R + math.log(1 - math.exp(log_L - log_R))
        else:
            return 0, 0  # f = 0

