A = list(range(1, m+1))
B = list(range(m+1, 2*m))  # 1009 to 2015

# Check sign of f at many points
# Check at half-integers between 0.5 and 2015.5
test_points = [i + 0.5 for i in range(0, 2016)]
# Also check outside range
test_points.extend([-10, -1, 0, 2016, 2020, 2100, 10000])

signs = set()
min_log_abs = float('inf')
for x_val in test_points:
    s, la = f_value(x_val, A, B)
    signs.add(s)
    if la < min_log_abs and la > 0:
        min_log_abs = la

print(f"Number of test points: {len(test_points)}")
print(f"Distinct signs: {signs}")
print(f"Min log|f| (among nonzero): {min_log_abs}")
print(f"Min |f|: {math.exp(min_log_abs) if min_log_abs < float('inf') else 'N/A'}")

# Also check at the integers in A and B
for k in A[:5] + A[-5:] + B[:5] + B[-5:]:
    s, la = f_value(float(k), A, B)
    print(f"  f({k}): sign={s}, log_abs={la}")
