def f_sign_and_log(x, A, B):
    """Return (sign, log|f(x)|) where f(x) = L(x) - R(x)."""
    log_L, sign_L = log_prod(x, A)
    log_R, sign_R = log_prod(x, B)

    if sign_L == 0:
        return -sign_R, log_R
    if sign_R == 0:
        return sign_L, log_L

    if sign_L != sign_R:
        # f = sign_L * exp(log_L) - sign_R * exp(log_R)
